namespace RealmGate.Server;
public enum RuntimeIntegrationOwner { MajorMud, Worldgroup, Shared, ExternalModule, UnknownNativeBoundary }
public sealed record RuntimeIntegrationBoundary(string Id,RuntimeIntegrationOwner Owner,bool Enabled,IReadOnlySet<string> AllowedOperations,bool RequiresHostAuthorization,bool AuditRequired);
public sealed record RuntimeIntegrationRequest(string BoundaryId,string Operation,string ActorId,bool HostAuthenticated,string? AccountId,string? SessionId,string CorrelationId);
public sealed record RuntimeIntegrationDispatch(string BoundaryId,string Operation,RuntimeIntegrationOwner Owner,string CorrelationId,string? AccountId,string? SessionId);
public sealed record RuntimeIntegrationResult(bool Success,RuntimeIntegrationDispatch? Dispatch,IReadOnlyList<string> Errors,bool AuditRequired);
public sealed class RuntimeWorldgroupIntegrationService
{
 private readonly Dictionary<string,RuntimeIntegrationBoundary> _boundaries;
 public RuntimeWorldgroupIntegrationService(IEnumerable<RuntimeIntegrationBoundary> boundaries){_boundaries=boundaries.ToDictionary(x=>x.Id,StringComparer.OrdinalIgnoreCase);if(_boundaries.Count==0||_boundaries.Values.Any(x=>string.IsNullOrWhiteSpace(x.Id)||x.AllowedOperations.Count==0))throw new ArgumentException("integration-boundaries-invalid");}
 public RuntimeIntegrationResult Authorize(RuntimeIntegrationRequest r){var e=new List<string>();if(string.IsNullOrWhiteSpace(r.BoundaryId)||string.IsNullOrWhiteSpace(r.Operation)||string.IsNullOrWhiteSpace(r.ActorId)||string.IsNullOrWhiteSpace(r.CorrelationId))e.Add("integration-request-invalid");if(!_boundaries.TryGetValue(r.BoundaryId,out var b))return new(false,null,[..e,"integration-boundary-unknown"],true);if(!b.Enabled)e.Add("integration-boundary-disabled");if(!b.AllowedOperations.Contains(r.Operation))e.Add("integration-operation-denied");if(b.RequiresHostAuthorization&&!r.HostAuthenticated)e.Add("host-authorization-required");if((b.Owner==RuntimeIntegrationOwner.Worldgroup||b.Owner==RuntimeIntegrationOwner.Shared)&&string.IsNullOrWhiteSpace(r.SessionId))e.Add("host-session-required");if(b.Owner==RuntimeIntegrationOwner.Worldgroup&&string.IsNullOrWhiteSpace(r.AccountId))e.Add("host-account-required");if(b.Owner==RuntimeIntegrationOwner.UnknownNativeBoundary)e.Add("native-boundary-unresolved");if(e.Count>0)return new(false,null,e,b.AuditRequired||true);return new(true,new(r.BoundaryId,r.Operation,b.Owner,r.CorrelationId,r.AccountId,r.SessionId),[],b.AuditRequired);}
 public IReadOnlyList<string> ValidateState(){var e=new List<string>();foreach(var b in _boundaries.Values){if(b.Owner==RuntimeIntegrationOwner.UnknownNativeBoundary&&b.Enabled)e.Add("unknown-native-boundary-enabled:"+b.Id);if(b.AllowedOperations.Any(string.IsNullOrWhiteSpace))e.Add("invalid-operation:"+b.Id);}return e;}
}
